html:
{%- set ev = get_economic_evaluation(doc.name) -%}
{%- set cur = ev.currency -%}
{%- set t = ev.totals -%}
{%- set f = ev.financing -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{%- endmacro -%}
{%- macro pct(v) -%}{{ "%.1f"|format(v or 0) }}%{%- endmacro -%}
{%- macro srclabel(code) -%}
{%- if code == "buying_item_price" -%}precio de compra
{%- elif code == "last_purchase_rate" -%}última compra
{%- elif code == "valuation_rate" -%}valuación
{%- elif code == "no_purchase" -%}sin compra
{%- else -%}{{ code }}{%- endif -%}
{%- endmacro -%}
<style>
  #toolbar, .print-toolbar, .action-banner { display:none !important; }
  .ee { color:#243040; font-family:-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; font-size:11px; line-height:1.4; }
  .ee .band { border-bottom:3px solid #1e3a5f; padding-bottom:8px; margin-bottom:14px; }
  .ee .band h1 { font-size:22px; margin:0; color:#1e3a5f; letter-spacing:.01em; }
  .ee .band .meta { color:#6b7787; font-size:11px; margin-top:3px; }
  .ee .band .meta b { color:#3a4658; }
  .ee h2 { font-size:13px; text-transform:uppercase; letter-spacing:.06em; color:#1e3a5f;
           border-bottom:1px solid #c9d3df; padding-bottom:3px; margin:18px 0 8px; }
  .ee h3 { font-size:12px; color:#3a4658; margin:12px 0 4px; }
  .ee p.lead { font-size:11.5px; color:#3a4658; background:#f4f7fb; border-left:3px solid #1e3a5f;
               padding:8px 12px; margin:6px 0 12px; border-radius:0 4px 4px 0; }
  .ee table { width:100%; border-collapse:collapse; margin:4px 0 6px; }
  .ee th, .ee td { padding:4px 7px; font-size:10.5px; border-bottom:1px solid #e4e9f0; }
  .ee th { text-align:left; color:#6b7787; font-weight:600; border-bottom:1.5px solid #c9d3df;
           text-transform:uppercase; font-size:9px; letter-spacing:.03em; }
  .ee td.n, .ee th.n { text-align:right; white-space:nowrap; }
  .ee tr.sub td { font-weight:700; color:#1e3a5f; border-top:1.5px solid #c9d3df; border-bottom:none; background:#f7f9fc; }
  .ee tr.grand td { font-weight:700; color:#1e3a5f; border-top:2px solid #1e3a5f; background:#eef3f9; }
  .ee .pos { color:#1a7a44; } .ee .neg { color:#c0392b; }
  .ee .muted { color:#8592a3; }
  .ee .empty { color:#8592a3; font-style:italic; padding:5px 0 10px; }
  .ee .kpi-strip { width:100%; border-collapse:collapse; margin:6px 0 4px; }
  .ee .kpi-strip td { border:none; border-right:1px solid #e4e9f0; padding:6px 12px; vertical-align:top; }
  .ee .kpi-strip td:last-child { border-right:none; }
  .ee .kpi-strip .l { color:#6b7787; font-size:8.5px; text-transform:uppercase; letter-spacing:.03em; }
  .ee .kpi-strip .v { font-size:14px; font-weight:700; color:#1e3a5f; margin-top:1px; }
  .ee .kpi-strip .v.small { font-size:12px; }
  .ee .warn { border-left:3px solid #e0a800; background:#fdf9ec; color:#7a5b00; padding:5px 10px; font-size:10px; margin:4px 0; }
  .ee .annex { page-break-before:always; }
  .ee .trz { border-bottom:1px solid #eef1f5; padding:4px 0; font-size:10px; }
  .ee .trz b { color:#1e3a5f; }
  .ee .trz .c { color:#6b7787; }
  .ee .fin-note { font-size:10px; color:#6b7787; margin:6px 0; }
  .ee .cat-h { font-size:11px; font-weight:700; color:#1e3a5f; margin:14px 0 4px; text-transform:uppercase; letter-spacing:.04em; }
  .ee .apu { border:1px solid #d7dfe9; border-radius:5px; padding:8px 10px; margin:8px 0; page-break-inside:avoid; }
  .ee .apu-h { font-weight:700; color:#1e3a5f; font-size:11.5px; }
  .ee .apu-h .tag { display:inline-block; font-size:8.5px; background:#1e3a5f; color:#fff; padding:1px 6px; border-radius:8px; margin-right:5px; vertical-align:middle; letter-spacing:.04em; }
  .ee .apu-com { color:#3a4658; font-size:10.5px; margin:2px 0 5px; }
  .ee .apu-t { width:100%; border-collapse:collapse; margin:2px 0; }
  .ee .apu-t th, .ee .apu-t td { padding:2.5px 6px; font-size:10px; border-bottom:1px solid #eef1f5; }
  .ee .apu-t th { font-size:8.5px; }
  .ee .apu-t tr.itot td { font-weight:700; color:#1e3a5f; border-top:1px solid #c9d3df; border-bottom:none; }
  .ee .apu-r { margin-top:5px; padding-top:4px; border-top:1px solid #e4e9f0; font-size:10.5px; color:#3a4658; }
  .ee .apu-r b { color:#1e3a5f; }
  .ee .pool-note { color:#8592a3; font-size:9.5px; font-style:italic; margin:2px 0 6px; }
  .ee .prof-h { font-size:9px; text-transform:uppercase; letter-spacing:.04em; color:#6b7787; margin:5px 0 1px; }
  .ee .keep { page-break-inside:avoid; }
  .ee tr.permes td { background:#eef3f9; font-weight:700; color:#1e3a5f; font-size:9.5px; text-transform:uppercase; letter-spacing:.03em; }
  .ee h2, .ee h3, .ee .cat-h { page-break-after:avoid; break-after:avoid; }
  .ee .band, .ee .kpi-strip { page-break-inside:avoid; }
</style>

<div class="ee">

  <div class="band">
    <h1>Evaluación Económica</h1>
    <div class="meta">
      <b>{{ ev.proposal_title or ev.quotation }}</b> &nbsp;·&nbsp; {{ ev.quotation }}
      &nbsp;·&nbsp; Cliente: {{ ev.customer or "—" }}
      &nbsp;·&nbsp; Plazo {{ ev.term_months }} meses
      &nbsp;·&nbsp; {{ cur }}
      &nbsp;·&nbsp; {% if ev.is_frozen %}Versión congelada{% else %}Proyección (Borrador){% endif %}
    </div>
  </div>

  <!-- A · RESUMEN ECONÓMICO (data-driven, sin narrativa) -->
  <h2>Resumen económico</h2>
  <table class="kpi-strip">
    <tr>
      <td><div class="l">Ingreso</div><div class="v">{{ money(t.revenue) }}</div></td>
      <td><div class="l">Costo externo</div><div class="v small">{{ money(t.external) }}</div></td>
      <td><div class="l">Esfuerzo</div><div class="v small">{{ money(t.labor) }}</div></td>
      <td><div class="l">Costo financiero</div><div class="v small {{ 'neg' if t.financial_cost else '' }}">{{ money(t.financial_cost) }}</div></td>
      <td><div class="l">Costo total</div><div class="v small">{{ money(t.total_cost_with_financing) }}</div></td>
    </tr>
    <tr>
      <td><div class="l">Margen operativo</div><div class="v small {{ 'pos' if t.margin >= 0 else 'neg' }}">{{ money(t.margin) }}</div></td>
      <td><div class="l">Margen final</div><div class="v {{ 'pos' if t.margin_after_financing >= 0 else 'neg' }}">{{ money(t.margin_after_financing) }}</div></td>
      <td><div class="l">Margen final %</div><div class="v {{ 'pos' if t.margin_after_financing >= 0 else 'neg' }}">{{ pct(t.margin_after_financing_pct) }}</div></td>
      <td><div class="l">Plazo</div><div class="v small">{{ ev.term_months }} meses</div></td>
      <td><div class="l">Horizonte</div><div class="v small">{{ ev.economic_horizon_months }} meses</div></td>
    </tr>
  </table>
  {%- for w in ev.warnings %}<div class="warn">⚠ {{ w.message }}</div>{%- endfor %}

  <!-- B · COMPOSICIÓN ECONÓMICA (APU por componente vendido) -->
  {%- macro eff_rows(l) -%}
    {%- for e in l.effort %}
    <tr><td>{{ e.activity }}{% if e.designation %} · {{ e.designation }}{% endif %}</td>
        <td class="n">{{ e.hours|round(1) }} h × {{ money(e.rate) }}</td>
        <td class="muted">{% for m in e.periods %}M{{ m }}{% if not loop.last %},{% endif %}{% endfor %}</td>
        <td class="n">{{ money(e.cost) }}</td></tr>
    {%- endfor %}
  {%- endmacro -%}
  {%- macro prof_summary(l) -%}
    {%- if l.effort_by_profile %}
    <div class="prof-h">Resumen de esfuerzo por perfil</div>
    <table class="apu-t">
      <thead><tr><th>Perfil</th><th class="n">Horas</th><th class="n">Costo</th></tr></thead>
      <tbody>
        {%- for p in l.effort_by_profile %}
        <tr><td>{{ p.designation or "—" }}</td><td class="n">{{ p.hours|round(1) }} h</td><td class="n">{{ money(p.cost) }}</td></tr>
        {%- endfor %}
        <tr class="itot"><td>Total</td><td class="n">{{ l.effort_by_profile|sum(attribute='hours')|round(1) }} h</td><td class="n">{{ money(l.labor) }}</td></tr>
      </tbody>
    </table>
    {%- endif %}
  {%- endmacro -%}
  {%- macro apu_oneshot(l, capex) -%}
  <div class="apu">
    <div class="apu-h"><span class="tag">{{ l.group }}</span>{{ l.label }}</div>
    <div class="apu-com">Cantidad {{ l.qty|round(2) }} · Precio unitario {{ money(l.unit_price) }} · Ingreso {{ money(l.revenue) }}</div>
    <table class="apu-t">
      <thead><tr><th>Concepto (insumo)</th><th class="n">Detalle</th><th>Cuándo</th><th class="n">Importe</th></tr></thead>
      <tbody>
        {%- if l.external > 0 %}<tr><td>{{ "Adquisición" if capex else "Compra / insumo" }}</td><td class="n">{{ l.qty|round(2) }} × {{ money(l.external_unit_cost) }}</td><td class="muted">Mes 0</td><td class="n">{{ money(l.external) }}</td></tr>{%- endif %}
        {{ eff_rows(l) }}
        {%- if not l.external and not l.effort %}<tr><td colspan="4" class="muted">Sin costo externo ni esfuerzo atribuible.</td></tr>{%- endif %}
        <tr class="itot"><td>Costo integrado</td><td colspan="2">{% if capex and l.qty > 1 %}unitario {{ money(l.integrated_cost / l.qty) }}{% endif %}</td><td class="n">{{ money(l.integrated_cost) }}</td></tr>
      </tbody>
    </table>
    {{ prof_summary(l) }}
    <div class="apu-r">Ingreso {{ money(l.revenue) }} · Costo integrado {{ money(l.integrated_cost) }} · <b class="{{ 'pos' if l.margin >= 0 else 'neg' }}">Margen {{ money(l.margin) }} ({{ "%.1f"|format(l.margin_pct) }}%)</b></div>
  </div>
  {%- endmacro -%}
  {%- macro apu_mrc(l) -%}
  <div class="apu">
    <div class="apu-h"><span class="tag">MRC</span>{{ l.label }}</div>
    <div class="apu-com">Cantidad {{ l.qty|round(2) }} · {{ money(l.revenue_per_period) }}/mes · {{ l.occurrences }} meses · Ingreso contractual {{ money(l.revenue) }}</div>
    <table class="apu-t">
      <thead><tr><th>Concepto (insumo)</th><th class="n">Detalle</th><th>Cuándo</th><th class="n">Importe contractual</th></tr></thead>
      <tbody>
        {%- if l.external > 0 %}<tr><td>Insumo recurrente</td><td class="n">{{ money(l.external_per_period) }}/mes × {{ l.occurrences }}</td><td class="muted">cada mes</td><td class="n">{{ money(l.external) }}</td></tr>{%- endif %}
        {{ eff_rows(l) }}
        {%- if not l.external and not l.effort %}<tr><td colspan="4" class="muted">Sin costo externo ni esfuerzo atribuible.</td></tr>{%- endif %}
        <tr class="itot"><td>Costo integrado contractual</td><td colspan="2"></td><td class="n">{{ money(l.integrated_cost) }}</td></tr>
      </tbody>
    </table>
    {{ prof_summary(l) }}
    <div class="apu-r">Margen recurrente mensual (antes de esfuerzo puntual): ingreso {{ money(l.revenue_per_period) }} − costo recurrente {{ money(l.external_per_period) }} = {{ money(l.revenue_per_period - l.external_per_period) }}/mes.
      <br>Margen contractual integrado: ingreso {{ money(l.revenue) }} · costo {{ money(l.integrated_cost) }} · <b class="{{ 'pos' if l.margin >= 0 else 'neg' }}">margen {{ money(l.margin) }} ({{ "%.1f"|format(l.margin_pct) }}%)</b></div>
  </div>
  {%- endmacro -%}

  <h2>Composición económica — integración por componente</h2>

  {%- set nrc_sold = ev.groups.NRC.lines|selectattr('origin','equalto','sold')|list %}
  <div class="cat-h">NRC · Cargos no recurrentes</div>
  {%- if not nrc_sold %}<div class="empty">Sin componentes NRC vendidos.</div>{%- endif %}
  {%- for l in nrc_sold %}{{ apu_oneshot(l, false) }}{%- endfor %}

  {%- set mrc_sold = ev.groups.MRC.lines|selectattr('origin','equalto','sold')|list %}
  <div class="cat-h">MRC · Cargos recurrentes mensuales</div>
  {%- if not mrc_sold %}<div class="empty">Sin componentes MRC vendidos.</div>{%- endif %}
  {%- for l in mrc_sold %}{{ apu_mrc(l) }}{%- endfor %}

  {%- set capex_sold = ev.groups.CAPEX.lines|selectattr('origin','equalto','sold')|list %}
  <div class="cat-h">CAPEX · Inversión en infraestructura</div>
  {%- if not capex_sold %}<div class="empty">Sin componentes CAPEX vendidos.</div>{%- endif %}
  {%- for l in capex_sold %}{{ apu_oneshot(l, true) }}{%- endfor %}

  {%- set req = ev.groups.NRC.lines|selectattr('origin','equalto','required')|list
                + ev.groups.MRC.lines|selectattr('origin','equalto','required')|list
                + ev.groups.CAPEX.lines|selectattr('origin','equalto','required')|list %}
  <div class="keep">
    <div class="cat-h">Costos requeridos no asignados</div>
    {%- if not req %}<div class="empty">Sin costos requeridos no asignados.</div>
    {%- else %}
    <table>
      <thead><tr><th>Concepto</th><th>Tipo</th><th class="n">Costo externo</th><th class="n">Esfuerzo</th><th class="n">Total</th></tr></thead>
      <tbody>
        {%- for l in req %}
        <tr><td>{{ l.label }}</td><td>{{ l.group }}</td><td class="n">{{ money(l.external) }}</td><td class="n">{{ money(l.labor) }}</td><td class="n">{{ money(l.integrated_cost) }}</td></tr>
        {%- endfor %}
        <tr class="sub"><td>Total no asignado</td><td></td><td class="n">{{ money(ev.apu.unassigned_external) }}</td><td class="n">{{ money(ev.apu.unassigned_labor) }}</td><td class="n">{{ money(ev.apu.unassigned_cost) }}</td></tr>
      </tbody>
    </table>
    {%- endif %}
  </div>

  <div class="keep">
    <div class="cat-h">Resultado integrado de la propuesta</div>
    <table style="max-width:70%">
      <tbody>
        <tr><td>Margen directo de componentes vendidos</td><td class="n">{{ money(ev.apu.sold_margin) }}</td></tr>
        <tr><td>(−) Costos requeridos no asignados</td><td class="n neg">{{ money(ev.apu.unassigned_cost) }}</td></tr>
        <tr class="sub"><td>Margen operativo</td><td class="n {{ 'pos' if t.margin >= 0 else 'neg' }}">{{ money(t.margin) }}</td></tr>
        {%- if f %}<tr><td>(−) Costo financiero</td><td class="n neg">{{ money(t.financial_cost) }}</td></tr>{%- endif %}
        <tr class="grand"><td>Margen final</td><td class="n {{ 'pos' if t.margin_after_financing >= 0 else 'neg' }}">{{ money(t.margin_after_financing) }}</td></tr>
        <tr><td>Margen final %</td><td class="n">{{ pct(t.margin_after_financing_pct) }}</td></tr>
      </tbody>
    </table>
  </div>

  <!-- C · COSTO DE ESFUERZO -->
  <h2>Costo de esfuerzo</h2>
  {%- if not ev.effort %}<div class="empty">Sin costo de esfuerzo.</div>
  {%- else %}
  {%- set profiles = ev.effort|map(attribute='designation')|unique|list %}
  <table>
    <thead><tr><th>Actividad</th><th>Perfil</th><th class="n">Horas</th><th class="n">Tarifa</th><th class="n">Costo</th><th>Periodos</th><th>Componente</th></tr></thead>
    <tbody>
      {%- for prof in profiles %}
      {%- set rows = ev.effort|selectattr('designation','equalto',prof)|list %}
      {%- for e in rows %}
      <tr><td>{{ e.activity }}</td><td>{{ e.designation or "—" }}</td><td class="n">{{ e.hours|round(1) }}</td>
        <td class="n">{{ money(e.rate) }}</td><td class="n">{{ money(e.cost) }}</td>
        <td class="muted">{% for m in e.periods %}M{{ m }}{% if not loop.last %},{% endif %}{% endfor %}</td>
        <td class="muted">{{ e.item_code or "—" }}</td></tr>
      {%- endfor %}
      <tr class="sub"><td>Subtotal {{ prof or "—" }}</td><td></td><td class="n">{{ rows|sum(attribute='hours')|round(1) }}</td><td></td><td class="n">{{ money(rows|sum(attribute='cost')) }}</td><td colspan="2"></td></tr>
      {%- endfor %}
      <tr class="grand"><td>Total esfuerzo</td><td></td><td class="n">{{ ev.effort_totals.hours|round(1) }}</td><td></td><td class="n">{{ money(ev.effort_totals.cost) }}</td><td colspan="2"></td></tr>
    </tbody>
  </table>
  {%- endif %}

  <!-- D · FINANCIAMIENTO -->
  <h2>Financiamiento CAPEX</h2>
  {%- if not f %}<div class="empty">Sin financiamiento CAPEX.</div>
  {%- else %}
  <table class="kpi-strip">
    <tr>
      <td><div class="l">CAPEX</div><div class="v small">{{ money(f.capex_external) }}</div></td>
      <td><div class="l">Financiado</div><div class="v small">{{ money(f.financed_amount) }} · {{ pct(f.financed_pct) }}</div></td>
      <td><div class="l">Plazo / tasa</div><div class="v small">{{ f.term_months }} m · {{ pct(f.annual_cost_rate) }}</div></td>
      <td><div class="l">Comisión</div><div class="v small">{{ money(f.fees) }}</div></td>
      <td><div class="l">Pago mensual</div><div class="v small">{{ money(f.payment) }}</div></td>
    </tr>
    <tr>
      <td><div class="l">Interés total</div><div class="v small neg">{{ money(f.total_interest) }}</div></td>
      <td><div class="l">Costo financiero</div><div class="v small neg">{{ money(f.financial_cost_total) }}</div></td>
      <td><div class="l">Margen antes</div><div class="v small {{ 'pos' if t.margin >= 0 else 'neg' }}">{{ money(t.margin) }}</div></td>
      <td><div class="l">Margen después</div><div class="v small {{ 'pos' if t.margin_after_financing >= 0 else 'neg' }}">{{ money(t.margin_after_financing) }}</div></td>
      <td><div class="l">Impacto</div><div class="v small neg">−{{ money(t.margin - t.margin_after_financing) }}</div></td>
    </tr>
  </table>
  <div class="fin-note">El principal no es costo económico (ya está en la adquisición del CAPEX); solo <b>interés + comisiones</b> = costo financiero ({{ money(f.total_interest) }} + {{ money(f.fees) }} = {{ money(f.financial_cost_total) }}). La amortización completa está en el anexo.</div>
  {%- endif %}

  <!-- E · EVOLUCIÓN ECONÓMICA -->
  <h2>Evolución económica (Mes 0…{{ ev.economic_horizon_months - 1 }})</h2>
  <table>
    <thead><tr><th>Periodo</th><th class="n">Ingreso</th><th class="n">Costo externo</th><th class="n">Esfuerzo</th><th class="n">Costo financiero</th><th class="n">Costo total</th><th class="n">Margen final</th></tr></thead>
    <tbody>
      {%- for p in ev.periods %}
      <tr><td>Mes {{ p.period }}</td><td class="n">{{ money(p.revenue) }}</td><td class="n">{{ money(p.external) }}</td>
        <td class="n">{{ money(p.labor) }}</td><td class="n">{{ money(p.financial_cost) }}</td>
        <td class="n">{{ money(p.total_cost_with_financing) }}</td>
        <td class="n {{ 'pos' if p.margin_after_financing >= 0 else 'neg' }}">{{ money(p.margin_after_financing) }}</td></tr>
      {%- endfor %}
      <tr class="grand"><td>Total</td><td class="n">{{ money(t.revenue) }}</td><td class="n">{{ money(t.external) }}</td>
        <td class="n">{{ money(t.labor) }}</td><td class="n">{{ money(t.financial_cost) }}</td>
        <td class="n">{{ money(t.total_cost_with_financing) }}</td>
        <td class="n {{ 'pos' if t.margin_after_financing >= 0 else 'neg' }}">{{ money(t.margin_after_financing) }}</td></tr>
    </tbody>
  </table>

  <!-- F · ANEXO: TRAZABILIDAD Y AMORTIZACIÓN -->
  <div class="annex">
    <h2>Anexo · Trazabilidad y detalle</h2>

    {%- if f %}
    <h3>Amortización del financiamiento</h3>
    <table>
      <thead><tr><th class="n">Cuota</th><th class="n">Saldo inicial</th><th class="n">Interés</th><th class="n">Capital</th><th class="n">Pago</th><th class="n">Saldo final</th></tr></thead>
      <tbody>
        {%- if f.fees %}<tr><td class="n">0</td><td class="n">—</td><td class="n">{{ money(f.fees) }}</td><td class="n">—</td><td class="n">{{ money(f.fees) }}</td><td class="n">{{ money(f.financed_amount) }}</td></tr>{%- endif %}
        {%- for s in f.schedule %}
        <tr><td class="n">{{ s.period }}</td><td class="n">{{ money(s.opening) }}</td><td class="n">{{ money(s.interest) }}</td><td class="n">{{ money(s.principal) }}</td><td class="n">{{ money(s.payment) }}</td><td class="n">{{ money(s.closing) }}</td></tr>
        {%- endfor %}
        <tr class="grand"><td class="n">Σ</td><td></td><td class="n">{{ money(f.total_interest) }}</td><td class="n">{{ money(f.financed_amount) }}</td><td class="n">{{ money(f.financed_amount + f.total_interest) }}</td><td class="n">0</td></tr>
      </tbody>
    </table>
    {%- endif %}

    <h3>Trazabilidad temporal</h3>
    <table>
      <thead><tr><th>Tipo</th><th>Componente / actividad</th><th>Desde</th><th>Hasta</th><th>Frecuencia / distribución</th><th class="n">Importe</th></tr></thead>
      <tbody>
        {%- for r in ev.temporal %}
        <tr>
          <td>{{ r.type }}</td>
          <td>{{ r.component }}{% if r.item_code %} <span class="muted">· {{ r.item_code }}</span>{% endif %}</td>
          <td>M{{ r["from"] }}</td><td>M{{ r.to }}</td>
          <td>{{ r.frequency }}</td>
          <td class="n">{{ money(r.amount) }}{% if r.monthly %} / mes{% elif r.frequency == "Distribuido" %} total{% endif %}</td>
        </tr>
        {%- endfor %}
      </tbody>
    </table>

    <h3>Controles de reconciliación</h3>
    <table style="max-width:60%">
      <tbody>
        <tr><td>Σ ingreso NRC+MRC+CAPEX = ingreso total</td><td class="n">{{ money(ev.groups.NRC.revenue + ev.groups.MRC.revenue + ev.groups.CAPEX.revenue) }} = {{ money(t.revenue) }}</td></tr>
        <tr><td>Σ costo externo por grupo = total</td><td class="n">{{ money(ev.groups.NRC.external + ev.groups.MRC.external + ev.groups.CAPEX.external) }} = {{ money(t.external) }}</td></tr>
        <tr><td>Costo de esfuerzo detallado = total</td><td class="n">{{ money(ev.effort_totals.cost) }} = {{ money(t.labor) }}</td></tr>
        {%- if f %}<tr><td>Interés + comisiones = costo financiero</td><td class="n">{{ money(f.total_interest + f.fees) }} = {{ money(f.financial_cost_total) }}</td></tr>{%- endif %}
        <tr><td>Costo operativo + financiero = costo total</td><td class="n">{{ money(t.total_cost) }} + {{ money(t.financial_cost) }} = {{ money(t.total_cost_with_financing) }}</td></tr>
        <tr><td>Ingreso − costo total = margen final</td><td class="n">{{ money(t.revenue) }} − {{ money(t.total_cost_with_financing) }} = {{ money(t.margin_after_financing) }}</td></tr>
      </tbody>
    </table>
  </div>

</div>
